// Regenerate src/prismicio-types.d.ts from customtypes/ and src/lib/slices/.
//
//   node scripts/regen-prismic-types.mjs            # dry run — reports the drift
//   node scripts/regen-prismic-types.mjs --write    # regenerate + format
//
// WHY THIS EXISTS. That file says "Code generated by Slice Machine. DO NOT
// EDIT.", and until now there was no way to obey both halves of that sentence:
// the adapter writes it from a custom-type WRITE hook, which only fires through
// Slice Machine's UI. `start-slicemachine` boots the server and regenerates
// nothing. So the honest options were "open the UI and click something" or
// "hand-edit the file it tells you not to hand-edit", and the file quietly went
// stale: measured on 2026-08-12 it was missing 39 types — four entire slices
// (ExamTimeline, FirstVisitToc, QuestionList, ServiceCategoryBand) and the
// variations of Hero, Carousel and CollectionList — and its page slice union
// still listed 11 blux_* choices the model had already dropped.
//
// TWO PRETTIER PASSES, deliberately. Slice Machine emits a `} & // comment`
// construct that prettier rewrites into a form it then rewrites again: pass 1
// and pass 2 produce different files, pass 3 equals pass 2. One pass leaves the
// file dirty, which matters more than it looks — the fleet's lint audit globs
// `**/*.{ts,js,svelte}` and consults neither .prettierignore nor .gitignore, so
// it checks files `pnpm lint` never sees. The standing rule (commit 4403220) is
// to FORMAT this file rather than ignore it, so that the site's own lint and the
// nightly audit resolve identically.
import { execFileSync } from "node:child_process";
import { existsSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import { createRequire } from "node:module";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = join(HERE, "..");
const TYPES = join(ROOT, "src", "prismicio-types.d.ts");
const WRITE = process.argv.includes("--write");
const require = createRequire(import.meta.url);

/**
 * Load @slicemachine/manager's CommonJS build.
 *
 * Two wrinkles, both load-bearing. It is not a direct dependency — it arrives
 * under slice-machine-ui — so the pnpm store is searched when the plain resolve
 * misses. And it must be the .cjs build: the ESM one directory-imports
 * @prismicio/types-internal/lib/customtypes, which Node refuses
 * (ERR_UNSUPPORTED_DIR_IMPORT).
 */
function loadManager() {
  try {
    return require("@slicemachine/manager/dist/index.cjs");
  } catch {
    /* not hoisted — fall through to the store */
  }
  const store = join(ROOT, "node_modules", ".pnpm");
  if (!existsSync(store))
    throw new Error("node_modules/.pnpm not found — run `pnpm install` first.");
  const dir = readdirSync(store).find((d) =>
    d.startsWith("@slicemachine+manager@"),
  );
  if (!dir)
    throw new Error(
      "@slicemachine/manager is not installed. It ships with slice-machine-ui;\n" +
        "run `pnpm install` and try again.",
    );
  return require(
    join(
      store,
      dir,
      "node_modules",
      "@slicemachine",
      "manager",
      "dist",
      "index.cjs",
    ),
  );
}

const TYPES_DIR = join(ROOT, "customtypes");
const modelPath = (id) => join(TYPES_DIR, id, "index.json");

const before = existsSync(TYPES) ? readFileSync(TYPES, "utf8") : "";

const { createSliceMachineManager } = loadManager();
const manager = createSliceMachineManager({ cwd: ROOT });
await manager.plugins.initPlugins();

// The write hook is what emits the types, so the models on disk get re-written
// to trigger it. That is not quite a no-op for customtypes/ — Slice Machine
// re-serialises each model in its own JSON layout — so a dry run has to be able
// to put them back, byte for byte.
const { models } = await manager.customTypes.readAllCustomTypes();
const modelsBefore = new Map(
  models
    .filter(({ model }) => existsSync(modelPath(model.id)))
    .map(({ model }) => [model.id, readFileSync(modelPath(model.id), "utf8")]),
);

for (const { model } of models) {
  const res = await manager.customTypes.updateCustomType({ model });
  if (res?.errors?.length)
    throw new Error(`${model.id}: ${JSON.stringify(res.errors).slice(0, 300)}`);
}

// ALWAYS format before comparing, even on a dry run. The generator's raw output
// never equals the committed file — that file is prettier-formatted, which is
// the whole point of the two passes below — so a dry run that diffed raw
// against formatted would report "stale" every single time and mean nothing.
// See the header: one pass is not enough, three is one too many.
for (let i = 0; i < 2; i++)
  execFileSync("npx", ["prettier", "--write", TYPES], {
    cwd: ROOT,
    stdio: "ignore",
  });

const after = readFileSync(TYPES, "utf8");
const names = (src) =>
  new Set(
    (src.match(/^(?:export )?(?:type|interface) [A-Za-z0-9_]+/gm) ?? []).map(
      (l) => l.split(" ").pop(),
    ),
  );
const wasNames = names(before);
const nowNames = names(after);
const added = [...nowNames].filter((n) => !wasNames.has(n));
const removed = [...wasNames].filter((n) => !nowNames.has(n));

console.log(`custom types: ${models.map((m) => m.model.id).join(", ")}`);
console.log(`types declared: ${wasNames.size} → ${nowNames.size}`);
if (added.length) console.log(`  + ${added.join(", ")}`);
if (removed.length) console.log(`  - ${removed.join(", ")}`);

if (!WRITE) {
  // There is no read-only mode for the hook, so the dry run undoes itself:
  // the .d.ts and every model file go back exactly as they were.
  for (const [id, src] of modelsBefore) writeFileSync(modelPath(id), src);
  writeFileSync(TYPES, before);
}

if (before === after) {
  console.log("\nsrc/prismicio-types.d.ts is up to date.");
} else if (WRITE) {
  console.log("\nsrc/prismicio-types.d.ts regenerated. Commit it.");
} else {
  console.log(
    "\nsrc/prismicio-types.d.ts is STALE (restored — nothing was changed).\n" +
      "Re-run with --write to regenerate it.",
  );
  process.exitCode = 1;
}
